import hashlib, hmac, uuid
chal="944f3240-f5ac-4667-93b4-fd9bfda459fe"
sec="mysecret"
resp="a9e950c84b293a11769a1994671c463dad95bb9a1e1873263e618e00a69429b9"

def try_hash(data: bytes):
    for name, fn in [
        ("sha256", lambda d: hashlib.sha256(d).hexdigest()),
        ("sha512-256?", lambda d: hashlib.sha512(d).hexdigest()[:64]),
        ("sha384?", lambda d: hashlib.sha384(d).hexdigest()[:64]),
        ("blake2b256", lambda d: hashlib.blake2b(d, digest_size=32).hexdigest()),
        ("blake2s256", lambda d: hashlib.blake2s(d).hexdigest()),
        ("md5+sha?", lambda d: hashlib.md5(d).hexdigest()+hashlib.md5(d).hexdigest()),
    ]:
        try:
            h=fn(data)
            if h==resp:
                print(f"MATCH {name} for {data!r}")
        except Exception as e:
            pass

# try many combos
seps=["",":","-","_"," ","\n","\x00","|"]
chal_vars=[chal, chal.replace("-",""), chal.upper(), chal.lower()]
sec_vars=[sec]
# also uuid bytes
chal_bytes_vars=[chal.encode(), chal.replace("-","").encode(), uuid.UUID(chal).bytes, uuid.UUID(chal).bytes_le]
sec_bytes=sec.encode()

for cb in chal_bytes_vars:
    for sep in seps:
        sep_b=sep.encode()
        for order in [(cb,sep_b,sec_bytes),(sec_bytes,sep_b,cb)]:
            data=b"".join(order)
            # try hashes
            for hname, hfn in [("sha256",hashlib.sha256),("blake2b32",lambda d: hashlib.blake2b(d, digest_size=32)),("blake2s",hashlib.blake2s)]:
                try:
                    if hname=="sha256":
                        h=hashlib.sha256(data).hexdigest()
                    elif hname=="blake2b32":
                        h=hashlib.blake2b(data, digest_size=32).hexdigest()
                    else:
                        h=hashlib.blake2s(data).hexdigest()
                    if h==resp:
                        print(f"MATCH {hname} data={data!r}")
                except: pass
print("done brute1")

# try hmac variants
for cb in chal_bytes_vars:
    for key in [sec_bytes, chal.encode(), uuid.UUID(chal).bytes]:
        for msg in [cb, sec_bytes]:
            # avoid duplicate?
            for hname in ["sha256","sha512","blake2"]:
                try:
                    if hname=="sha256":
                        h=hmac.new(key, msg, hashlib.sha256).hexdigest()
                    elif hname=="sha512":
                        h=hmac.new(key, msg, hashlib.sha512).hexdigest()[:64]
                    else:
                        continue
                    if h==resp:
                        print(f"MATCH hmac {hname} key={key!r} msg={msg!r}")
                except: pass
print("done brute2")
