{"command": "python3 - <<'PY'
import hashlib, hmac, uuid
pairs=[
 ("944f3240-f5ac-4667-93b4-fd9bfda459fe","a9e950c84b293a11769a1994671c463dad95bb9a1e1873263e618e00a69429b9","mysecret"),
]
chal, resp, sec = pairs[0]
print(f"chal={chal} sec={sec} resp={resp}")

def test_hash(data: bytes):
    results=[]
    # sha256
    results.append(("sha256", hashlib.sha256(data).hexdigest()))
    results.append(("sha3_256", hashlib.sha3_256(data).hexdigest()))
    results.append(("sha512_256", hashlib.new('sha512_256', data).hexdigest() if 'sha512_256' in hashlib.algorithms_available else "N/A"))
    results.append(("blake2b32", hashlib.blake2b(data, digest_size=32).hexdigest()))
    results.append(("blake2s", hashlib.blake2s(data).hexdigest()))
    results.append(("sha224", hashlib.sha224(data).hexdigest()))
    # sha1 doubled?
    # try first 64 of sha512
    results.append(("sha512[:64]", hashlib.sha512(data).hexdigest()[:64]))
    results.append(("sha384[:64]", hashlib.sha384(data).hexdigest()[:64]))
    for n,h in results:
        if h==resp:
            print(f"MATCH {n} data={data!r}")
            return True
    return False

# try many data combos
import itertools
chal_strs=[chal, chal.replace("-",""), chal.upper(), chal.replace("-","").upper()]
sec_strs=[sec]
seps=["",":","-","_"," ","\n","\x00","|","/"]
found=False
for cs in chal_strs:
    for ss in sec_strs:
        for sep in seps:
            for data_str in [cs+sep+ss, ss+sep+cs]:
                if test_hash(data_str.encode()):
                    print(f"found data_str={data_str!r}")
                    found=True
print("done1 found?",found)

# try hmac sha3?
for cs in chal_strs:
    for data in [cs.encode(), sec.encode()]:
        for key in [cs.encode(), sec.encode()]:
            for algo in ["sha256","sha3_256"]:
                try:
                    if algo=="sha256":
                        h=hmac.new(key, data, hashlib.sha256).hexdigest()
                    else:
                        h=hmac.new(key, data, hashlib.sha3_256).hexdigest()
                    if h==resp:
                        print(f"MATCH hmac {algo} key={key!r} data={data!r}")
                except: pass
print("done2")

# try uuid bytes
for cb in [uuid.UUID(chal).bytes, uuid.UUID(chal).bytes_le]:
    for data in [cb+sec.encode(), sec.encode()+cb]:
        if test_hash(data):
            print(f"found uuid bytes data={data!r}")

# try hashing secret first?
# e.g., sha256(secret) hex then + challenge?
sec_sha256=hashlib.sha256(sec.encode()).hexdigest()
print(f"sec_sha256={sec_sha256}")
for cs in chal_strs:
    for data_str in [cs+sec_sha256, sec_sha256+cs, cs+":"+sec_sha256, sec_sha256+":"+cs]:
        if test_hash(data_str.encode()):
            print(f"found double {data_str!r}")

# try challenge hashed?
chal_sha256=hashlib.sha256(chal.encode()).hexdigest()
print(f"chal_sha256={chal_sha256}")
for data_str in [chal_sha256+sec, sec+chal_sha256]:
    if test_hash(data_str.encode()):
        print(f"found chal hashed {data_str!r}")
PY
"}

