{"command": "python3 - <<'PY'
import hashlib, hmac, uuid
chal="11111111-1111-1111-1111-111111111111"
sec="mysecret"
resp="977412a786804e439fc746417412d295adb56cb0b86ed268311254cd34939b4e"

chal_opts={
    "str": chal.encode(),
    "nodash": chal.replace("-","").encode(),
    "bytes": uuid.UUID(chal).bytes,
    "bytes_le": uuid.UUID(chal).bytes_le,
}
sec_opts={
    "str": sec.encode(),
}

for cn, cb in chal_opts.items():
    for sn, sb in sec_opts.items():
        # hmac key=sb msg=cb
        for algo, name in [(hashlib.sha256,"sha256"), (hashlib.sha3_256,"sha3_256"), (hashlib.sha512,"sha512"), (hashlib.blake2b,"blake2b")]:
            try:
                if name=="sha512":
                    h=hmac.new(sb, cb, hashlib.sha512).hexdigest()[:64]
                elif name=="blake2b":
                    # hmac with blake2b? python's hmac can use any?
                    h=hmac.new(sb, cb, hashlib.blake2b).hexdigest()
                    # blake2b digest is 128 hex by default (64 bytes), need first 64?
                    h=h[:64]
                else:
                    h=hmac.new(sb, cb, algo).hexdigest()
                if h==resp:
                    print(f"MATCH hmac {name} key=sec({sn}) msg=chal({cn})")
                # reverse
                if name=="sha512":
                    h2=hmac.new(cb, sb, hashlib.sha512).hexdigest()[:64]
                elif name=="blake2b":
                    h2=hmac.new(cb, sb, hashlib.blake2b).hexdigest()[:64]
                else:
                    h2=hmac.new(cb, sb, algo).hexdigest()
                if h2==resp:
                    print(f"MATCH hmac {name} key=chal({cn}) msg=sec({sn})")
            except Exception as e:
                print(f"err {e}")

print("done hmac")
# try plain hash of hmac? e.g., sha256(hmac(...))?
