// ---------- messages ----------
#[derive(Serialize, Deserialize, Debug)]
enum ClientMessage {
    Hello(u16),
    Authenticate(String),
    Accept(uuid::Uuid),
}
#[derive(Serialize, Deserialize, Debug)]
enum ServerMessage {
    Challenge(uuid::Uuid),
    Hello(u16),
    Connection(uuid::Uuid),
    Error(String),
    Heartbeat,
}

fn send_msg<T: Serialize>(stream: &mut TcpStream, msg: &T) -> std::io::Result<()> {
    let mut data = serde_json::to_vec(msg).unwrap();
    data.push(0);
    stream.write_all(&data)?;
    stream.flush()?;
    Ok(())
}

// Buffered reader for null-delimited JSON
struct MsgReader {
    stream: TcpStream,
    buf: Vec<u8>,
}
impl MsgReader {
    fn new(stream: TcpStream) -> Self { Self { stream, buf: Vec::new() } }
    fn set_timeout(&self, d: Option<Duration>) -> std::io::Result<()> {
        self.stream.set_read_timeout(d)
    }
    // returns Ok(None) on clean EOF (0 bytes and no buffered data), Ok(Some(bytes without null)) on message, Err on timeout/parse/io
    fn read_raw(&mut self) -> std::io::Result<Option<Vec<u8>>> {
        loop {
            if let Some(pos) = self.buf.iter().position(|&b| b == 0) {
                let msg: Vec<u8> = self.buf.drain(..pos).collect();
                // remove null
                self.buf.remove(0);
                return Ok(Some(msg));
            }
            let mut tmp = [0u8; 4096];
            match self.stream.read(&mut tmp) {
                Ok(0) => {
                    if self.buf.is_empty() {
                        return Ok(None);
                    } else {
                        // EOF with partial data? treat as error? For now, return None? Actually partial without null is incomplete, treat as parse error later? But TCP close with partial should be considered EOF? We'll return None if no null? Hmm. For simplicity, if EOF with partial, treat as parse error via returning Some(partial) which will fail json parse.
                        // But to match original: if connection closes without null, it would be considered... Let's just return None if empty, else return Some(partial) to trigger parse error? Actually original would try to parse partial and fail with "unable to parse"? Or timeout? For EOF with partial, read returns 0, but buf has data, we should return that data as message (without null) to trigger parse error. Let's do that.
                        let remaining = std::mem::take(&mut self.buf);
                        return Ok(Some(remaining));
                    }
                }
                Ok(n) => {
                    self.buf.extend_from_slice(&tmp[..n]);
                }
                Err(e) => return Err(e),
            }
        }
    }
}

fn compute_auth(secret: &str, challenge: &uuid::Uuid) -> String {
    use sha2::{Sha256, Digest};
    use std::io::Write;
    // key = SHA256(secret)
    let mut hasher = Sha256::new();
    hasher.update(secret.as_bytes());
    let key = hasher.finalize();
    // HMAC-SHA256(key, msg=challenge.bytes)
    let msg = challenge.as_bytes();
    // manual HMAC
    const BLOCK: usize = 64;
    let mut key_block = [0u8; BLOCK];
    if key.len() > BLOCK {
        let mut h = Sha256::new();
        h.update(&key);
        let hk = h.finalize();
        key_block[..hk.len()].copy_from_slice(&hk);
    } else {
        key_block[..key.len()].copy_from_slice(&key);
    }
    let mut ipad = [0x36u8; BLOCK];
    let mut opad = [0x5cu8; BLOCK];
    for i in 0..BLOCK {
        ipad[i] ^= key_block[i];
        opad[i] ^= key_block[i];
    }
    let mut inner = Sha256::new();
    inner.update(&ipad);
    inner.update(msg);
    let inner_hash = inner.finalize();
    let mut outer = Sha256::new();
    outer.update(&opad);
    outer.update(&inner_hash);
    let out = outer.finalize();
    hex_encode(&out)
}
fn hex_encode(b: &[u8]) -> String {
    let mut s = String::with_capacity(b.len()*2);
    for &x in b {
        s.push(char::from_digit((x>>4) as u32, 16).unwrap());
        s.push(char::from_digit((x & 0xf) as u32, 16).unwrap());
    }
    s
}

// ---------- CLI ----------
fn build_cli() -> Command {
    Command::new("bore-cli")
        .version("0.6.0")
        .about("A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls.")
        .arg_required_else_help(true)
        .subcommand_required(true)
        .subcommand(
            Command::new("local")
                .about("Starts a local proxy to the remote server")
                .arg(Arg::new("LOCAL_PORT").help("The local port to expose").env("BORE_LOCAL_PORT").value_name("LOCAL_PORT").value_parser(clap::value_parser!(u16)).required(true))
                .arg(Arg::new("local-host").short('l').long("local-host").help("The local host to expose").value_name("HOST").default_value("localhost"))
                .arg(Arg::new("to").short('t').long("to").help("Address of the remote server to expose local ports to").value_name("TO").env("BORE_SERVER").required(true))
                .arg(Arg::new("port").short('p').long("port").help("Optional port on the remote server to select").value_name("PORT").default_value("0").value_parser(clap::value_parser!(u16)))
                .arg(Arg::new("secret").short('s').long("secret").help("Optional secret for authentication").value_name("SECRET").env("BORE_SECRET").hide_env_values(true))
        )
        .subcommand(
            Command::new("server")
                .about("Runs the remote proxy server")
                .arg(Arg::new("min-port").long("min-port").help("Minimum accepted TCP port number").value_name("MIN_PORT").env("BORE_MIN_PORT").default_value("1024").value_parser(clap::value_parser!(u16)))
                .arg(Arg::new("max-port").long("max-port").help("Maximum accepted TCP port number").value_name("MAX_PORT").env("BORE_MAX_PORT").default_value("65535").value_parser(clap::value_parser!(u16)))
                .arg(Arg::new("secret").short('s').long("secret").help("Optional secret for authentication").value_name("SECRET").env("BORE_SECRET").hide_env_values(true))
                .arg(Arg::new("bind-addr").long("bind-addr").help("IP address to bind to, clients must reach this").value_name("BIND_ADDR").default_value("0.0.0.0").value_parser(clap::value_parser!(IpAddr)))
                .arg(Arg::new("bind-tunnels").long("bind-tunnels").help("IP address where tunnels will listen on, defaults to --bind-addr").value_name("BIND_TUNNELS").value_parser(clap::value_parser!(IpAddr)))
        )
}

fn main() -> Result<()> {
    let matches = build_cli().get_matches();
    match matches.subcommand() {
        Some(("local", sub)) => {
            let local_port: u16 = sub.get_one::<u16>("LOCAL_PORT").copied().unwrap();
            let local_host: String = sub.get_one::<String>("local-host").cloned().unwrap();
            let to: String = sub.get_one::<String>("to").cloned().unwrap();
            let port: u16 = sub.get_one::<u16>("port").copied().unwrap();
            let secret: Option<String> = sub.get_one::<String>("secret").cloned();
            run_client(local_port, &local_host, &to, port, secret)
        }
        Some(("server", sub)) => {
            let min_port: u16 = sub.get_one::<u16>("min-port").copied().unwrap();
            let max_port: u16 = sub.get_one::<u16>("max-port").copied().unwrap();
            if min_port > max_port {
                eprintln!("error: port range is empty\n\nUsage: bore-cli <COMMAND>\n\nFor more information, try '--help'.");
                std::process::exit(2);
            }
            let secret: Option<String> = sub.get_one::<String>("secret").cloned();
            let bind_addr: IpAddr = sub.get_one::<IpAddr>("bind-addr").copied().unwrap();
            let bind_tunnels: Option<IpAddr> = sub.get_one::<IpAddr>("bind-tunnels").copied();
            run_server(min_port, max_port, secret, bind_addr, bind_tunnels)
        }
        _ => unreachable!(),
    }
}

// ---------- server ----------
struct PendingConn {
    stream: TcpStream,
    created: Instant,
}

fn run_server(min_port: u16, max_port: u16, secret: Option<String>, bind_addr: IpAddr, bind_tunnels: Option<IpAddr>) -> Result<()> {
    let tunnel_ip = bind_tunnels.unwrap_or(bind_addr);
    let listener = TcpListener::bind((bind_addr, CONTROL_PORT))?;
    server_log_info(None, "server listening", vec![("addr".to_string(), bind_addr.to_string())]);
    let pending: Arc<Mutex<HashMap<uuid::Uuid, PendingConn>>> = Arc::new(Mutex::new(HashMap::new()));
    // stale cleaner
    {
        let pending2 = pending.clone();
        std::thread::spawn(move || loop {
            std::thread::sleep(Duration::from_secs(1));
            let mut map = pending2.lock().unwrap();
            let now = Instant::now();
            let stale: Vec<uuid::Uuid> = map.iter().filter(|(_,v)| now.duration_since(v.created) >= STALE_TIMEOUT).map(|(k,_)| *k).collect();
            for id in stale {
                if let Some(_p) = map.remove(&id) {
                    // drop stream (close)
                    server_log_warn(None, "removed stale connection", vec![("id".to_string(), id.to_string())]);
                }
            }
        });
    }
    let secret = Arc::new(secret);
    for incoming in listener.incoming() {
        match incoming {
            Ok(stream) => {
                let peer = stream.peer_addr().unwrap();
                let pending = pending.clone();
                let secret = secret.clone();
                let min_port = min_port;
                let max_port = max_port;
                let tunnel_ip = tunnel_ip;
                std::thread::spawn(move || {
                    handle_server_conn(stream, peer, pending, secret, min_port, max_port, tunnel_ip);
                });
            }
            Err(e) => {
                // accept error? ignore?
                eprintln!("accept error: {}", e);
            }
        }
    }
    Ok(())
}

fn handle_server_conn(stream: TcpStream, peer: SocketAddr, pending: Arc<Mutex<HashMap<uuid::Uuid, PendingConn>>>, secret: Arc<Option<String>>, min_port: u16, max_port: u16, tunnel_ip: IpAddr) {
    let span = fmt_span_control(&peer);
    server_log_info(Some(span.clone()), "incoming connection", vec![]);
    // set read timeout for initial
    let _ = stream.set_read_timeout(Some(INITIAL_TIMEOUT));
    let mut reader = MsgReader::new(stream.try_clone().unwrap());
    let mut writer = stream.try_clone().unwrap();
    // If secret configured, send Challenge first (for ALL new connections, including Accept? But Accept should also get Challenge. However for no-secret, don't send.)
    // Actually for secret mode, every new connection gets Challenge, then expects Auth. But for Accept vs Hello, after Auth we distinguish.
    // For no-secret, directly expect Hello/Accept.
    if let Some(sec) = secret.as_ref().as_ref() {
        // secret mode: send Challenge
        let challenge = uuid::Uuid::new_v4();
        if send_msg(&mut writer, &ServerMessage::Challenge(challenge)).is_err() {
            server_log_info(Some(span.clone()), "connection exited", vec![]);
            return;
        }
        // read first message (Authenticate expected)
        let raw = match reader.read_raw() {
            Ok(Some(b)) => b,
            Ok(None) => {
                // EOF before message? treat as exited (no error)? But secret handshake timeout vs EOF? For EOF immediate, should be connection exited (no error)? Actually for secret with immediate close (no data), read_raw returns None (EOF). What does original do? It would timeout? No, immediate EOF should be connection exited (no handshake failed)? Let's check: In probe, secret timeout with no data (client stayed open, no send) gave handshake failed + Error sent. For immediate close, it would be EOF, not timeout. What does original do for immediate EOF? Probably connection exited (no handshake failed)? We haven't tested. For simplicity, treat None as connection exited (INFO).
                server_log_info(Some(span.clone()), "connection exited", vec![]);
                return;
            }
            Err(e) if e.kind() == std::io::ErrorKind::TimedOut || e.kind() == std::io::ErrorKind::WouldBlock => {
                let _ = send_msg(&mut writer, &ServerMessage::Error("timed out waiting for initial message".to_string()));
                server_log_warn(Some(span.clone()), "server handshake failed", vec![("err".to_string(), "timed out waiting for initial message".to_string())]);
                server_log_info(Some(span.clone()), "connection exited", vec![]);
                return;
            }
            Err(_) => {
                server_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), "unable to parse message".to_string())]);
                return;
            }
        };
        // try parse as ClientMessage
        // First, try to parse as generic ClientMessage to distinguish
        let parsed: Result<ClientMessage, _> = serde_json::from_slice(&raw);
        match parsed {
            Ok(ClientMessage::Authenticate(token)) => {
                // validate
                let expected = compute_auth(sec, &challenge);
                if token != expected {
                    let _ = send_msg(&mut writer, &ServerMessage::Error("invalid secret".to_string()));
                    server_log_warn(Some(span.clone()), "server handshake failed", vec![("err".to_string(), "invalid secret".to_string())]);
                    server_log_info(Some(span.clone()), "connection exited", vec![]);
                    return;
                }
                // auth ok, now read second message (Hello or Accept)
                // keep timeout 3s (already set)
                let raw2 = match reader.read_raw() {
                    Ok(Some(b)) => b,
                    Ok(None) => {
                        server_log_info(Some(span.clone()), "connection exited", vec![]);
                        return;
                    }
                    Err(e) if e.kind() == std::io::ErrorKind::TimedOut || e.kind() == std::io::ErrorKind::WouldBlock => {
                        server_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), "timed out waiting for initial message".to_string())]);
                        return;
                    }
                    Err(_) => {
                        server_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), "unable to parse message".to_string())]);
                        return;
                    }
                };
                let parsed2: Result<ClientMessage, _> = serde_json::from_slice(&raw2);
                match parsed2 {
                    Ok(ClientMessage::Hello(req_port)) => {
                        // handle as new control (same as no-secret Hello)
                        handle_server_hello(writer, reader, peer, span, req_port, pending, min_port, max_port, tunnel_ip);
                    }
                    Ok(ClientMessage::Accept(id)) => {
                        handle_server_accept(writer, peer, span, id, pending);
                    }
                    Ok(ClientMessage::Authenticate(_)) => {
                        // unexpected second auth? treat as parse error (no Error sent, warn)
                        server_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), "unable to parse message".to_string())]);
                        return;
                    }
                    Err(_) => {
                        server_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), "unable to parse message".to_string())]);
                        return;
                    }
                }
            }
            Ok(ClientMessage::Hello(_)) | Ok(ClientMessage::Accept(_)) => {
                // missing auth
                let _ = send_msg(&mut writer, &ServerMessage::Error("server requires secret, but no secret was provided".to_string()));
                server_log_warn(Some(span.clone()), "server handshake failed", vec![("err".to_string(), "server requires secret, but no secret was provided".to_string())]);
                server_log_info(Some(span.clone()), "connection exited", vec![]);
                return;
            }
            Err(_) => {
                let _ = send_msg(&mut writer, &ServerMessage::Error("unable to parse message".to_string()));
                server_log_warn(Some(span.clone()), "server handshake failed", vec![("err".to_string(), "unable to parse message".to_string())]);
                server_log_info(Some(span.clone()), "connection exited", vec![]);
                return;
            }
        }
    } else {
        // no secret: read first message, expect Hello or Accept
        let raw = match reader.read_raw() {
            Ok(Some(b)) => b,
            Ok(None) => {
                server_log_info(Some(span.clone()), "connection exited", vec![]);
                return;
            }
            Err(e) if e.kind() == std::io::ErrorKind::TimedOut || e.kind() == std::io::ErrorKind::WouldBlock => {
                server_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), "timed out waiting for initial message".to_string())]);
                return;
            }
            Err(_) => {
                server_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), "unable to parse message".to_string())]);
                return;
            }
        };
        let parsed: Result<ClientMessage, _> = serde_json::from_slice(&raw);
        match parsed {
            Ok(ClientMessage::Hello(req_port)) => {
                handle_server_hello(writer, reader, peer, span, req_port, pending, min_port, max_port, tunnel_ip);
            }
            Ok(ClientMessage::Accept(id)) => {
                handle_server_accept(writer, peer, span, id, pending);
            }
            Ok(ClientMessage::Authenticate(_)) => {
                server_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), "unable to parse message".to_string())]);
                return;
            }
            Err(_) => {
                server_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), "unable to parse message".to_string())]);
                return;
            }
        }
    }
}

fn handle_server_hello(writer: TcpStream, _reader: MsgReader, peer: SocketAddr, span: String, req_port: u16, pending: Arc<Mutex<HashMap<uuid::Uuid, PendingConn>>>, min_port: u16, max_port: u16, tunnel_ip: IpAddr) {
    let mut writer = writer;
    // check range (0 exempt)
    if req_port != 0 && (req_port < min_port || req_port > max_port) {
        let _ = send_msg(&mut writer, &ServerMessage::Error("client port number not in allowed range".to_string()));
        server_log_info(Some(span.clone()), "connection exited", vec![]);
        return;
    }
    // try bind tunnel
    let tunnel_listener = if req_port == 0 {
        // random in range
        // try up to 100 times? Or loop until success? If range empty? Already checked min<=max, so at least one port. Try random picks.
        let mut success: Option<(TcpListener, u16)> = None;
        for _ in 0..100 {
            let cand = rand::Rng::gen_range(&mut rand::thread_rng(), min_port..=max_port);
            match TcpListener::bind((tunnel_ip, cand)) {
                Ok(l) => { success = Some((l, cand)); break; }
                Err(e) if e.kind() == std::io::ErrorKind::AddrInUse => continue,
                Err(_) => continue,
            }
        }
        // if not success after 100, try sequential? Or try bind to 0 and check? For narrow range with all in use, after 100 tries still fail, then what? Should send port already in use? Let's just try to find free by iterating? Simpler: iterate all ports in range and try? But for large range (64512 ports), iterating is heavy. We'll just try random 100, if fail, send port already in use.
        match success {
            Some((l,_)) => l,
            None => {
                // check if any free? For simplicity, send port already in use
                let _ = send_msg(&mut writer, &ServerMessage::Error("port already in use".to_string()));
                server_log_info(Some(span.clone()), "connection exited", vec![]);
                return;
            }
        }
    } else {
        match TcpListener::bind((tunnel_ip, req_port)) {
            Ok(l) => l,
            Err(e) if e.kind() == std::io::ErrorKind::AddrInUse => {
                let _ = send_msg(&mut writer, &ServerMessage::Error("port already in use".to_string()));
                server_log_info(Some(span.clone()), "connection exited", vec![]);
                return;
            }
            Err(_) => {
                let _ = send_msg(&mut writer, &ServerMessage::Error("port already in use".to_string()));
                server_log_info(Some(span.clone()), "connection exited", vec![]);
                return;
            }
        }
    };
    let actual_port = tunnel_listener.local_addr().unwrap().port();
    // send Hello
    if send_msg(&mut writer, &ServerMessage::Hello(actual_port)).is_err() {
        server_log_info(Some(span.clone()), "connection exited", vec![]);
        return;
    }
    server_log_info(Some(span.clone()), "new client", vec![("host".to_string(), tunnel_ip.to_string()), ("port".to_string(), actual_port.to_string())]);
    // clear read timeout for control? Control after handshake doesn't read (except to detect disconnect via heartbeat send failures). We'll set no timeout and spawn threads.
    let _ = writer.set_read_timeout(None);
    // Need to handle control loop: heartbeat + tunnel accept + disconnect detection
    // Use Arc<Mutex<TcpStream>> for writer to share between heartbeat and Connection sends
    let writer_arc = Arc::new(Mutex::new(writer.try_clone().unwrap()));
    // Also need reader for disconnect detection? We'll spawn a thread that reads from control (discarding) to detect EOF.
    // Actually control stream (original) is used for reading? We have _reader which holds stream clone. We'll use it for disconnect detection in a thread.
    // Spawn heartbeat
    {
        let w = writer_arc.clone();
        std::thread::spawn(move || loop {
            std::thread::sleep(HEARTBEAT_INTERVAL);
            let mut g = w.lock().unwrap();
            if send_msg(&mut *g, &ServerMessage::Heartbeat).is_err() {
                break;
            }
        });
    }
    // Spawn disconnect detector (read discarding)
    {
        let mut r = _reader;
        let _ = r.set_timeout(None);
        // Use the underlying stream for reading? _reader.stream is a clone of original. We'll just read in loop discarding.
        std::thread::spawn(move || loop {
            let mut tmp = [0u8; 4096];
            // Use blocking read without timeout
            match r.stream.read(&mut tmp) {
                Ok(0) => break, // EOF
                Ok(_) => continue, // discard
                Err(_) => break,
            }
        });
    }
    // Main tunnel accept loop (blocking)
    // Need to be able to break when control disconnects? How to detect? The heartbeat thread will break on send fail, but tunnel accept loop is blocked on accept(). When control disconnects, we need to close tunnel listener to break accept(). How?
    // For simplicity, set tunnel_listener to nonblocking? Or use timeout? Alternative: Use `accept` with timeout via `set_nonblocking` + poll? Simpler: Make tunnel_listener nonblocking and poll with control check? Or just leave it blocking and when process exits, it will be cleaned? But when control disconnects, tunnel should be cleaned immediately (as observed: after client closes control, server logs connection exited and tunnel port freed). How to implement without complex?
    // Approach: Clone control writer to detect disconnect via heartbeat failure, and when heartbeat fails, close tunnel listener by dropping? But accept() is blocking, dropping listener from another thread will unblock? In std, dropping TcpListener while another thread is blocked in accept() will unblock with error? Possibly. Let's try: heartbeat thread holds writer_arc, when send fails, it could shutdown? But tunnel accept loop is on different thread (this one). We need coordination.
