        let mut writer = stream.try_clone().unwrap();
        if send_msg(&mut writer, &ClientMessage::Accept(id)).is_err() {
            client_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), "timed out waiting for initial message".to_string())]);
            return;
        }
        let _ = stream.set_read_timeout(None);
        let local_addr_str = format!("{}:{}", local_host, local_port);
        let local_addrs: Vec<SocketAddr> = match local_addr_str.to_socket_addrs() {
            Ok(a) => a.collect(),
            Err(_) => {
                client_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), format!("could not connect to {}:{}", local_host, local_port))]);
                return;
            }
        };
        let mut local_opt: Option<TcpStream> = None;
        for a in local_addrs {
            if let Ok(s) = TcpStream::connect(a) {
                local_opt = Some(s);
                break;
            }
        }
        let mut local = match local_opt {
            Some(s) => s,
            None => {
                client_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), format!("could not connect to {}:{}", local_host, local_port))]);
                return;
            }
        };
        proxy_and_log(stream, local, span);
    }
}

fn proxy_and_log(mut a: TcpStream, mut b: TcpStream, span: String) {
    let _ = a.set_read_timeout(None);
    let _ = b.set_read_timeout(None);
    let mut a_clone = a.try_clone().unwrap();
    let mut b_clone = b.try_clone().unwrap();
    // Need to detect errors for logging. We'll capture errors via channels? Simpler: Use io::copy and check result.
    // We'll spawn two threads and join, capturing success.
    let t1 = std::thread::spawn(move || -> std::io::Result<()> {
        let mut buf = [0u8; 8192];
        loop {
            let n = a.read(&mut buf)?;
            if n == 0 {
                let _ = b.shutdown(std::net::Shutdown::Write);
                break;
            }
            b.write_all(&buf[..n])?;
        }
        Ok(())
    });
    let t2 = std::thread::spawn(move || -> std::io::Result<()> {
        let mut buf = [0u8; 8192];
        loop {
            let n = b_clone.read(&mut buf)?;
            if n == 0 {
                let _ = a_clone.shutdown(std::net::Shutdown::Write);
                break;
            }
            a_clone.write_all(&buf[..n])?;
        }
        Ok(())
    });
    let r1 = t1.join().unwrap_or(Ok(()));
    let r2 = t2.join().unwrap_or(Ok(()));
    // If either had error (not EOF), log warn with error. How to get error? Our threads return Result, but they break on error with Err. Let's check.
    // Actually our threads return Ok(()) even on error? No, they use `?` which returns Err on read/write error. Good.
    // So r1/r2 are Results.
    let err = r1.err().or(r2.err());
    match err {
        Some(e) => {
            client_log_warn(Some(span.clone()), "connection exited with error", vec![("err".to_string(), e.to_string())]);
        }
        None => {
            client_log_info(Some(span.clone()), "connection exited", vec![]);
        }
    }
}

