        match parsed {
            Ok(ServerMessage::Challenge(ch)) => {
                let auth = compute_auth(&sec, &ch);
                send_msg(&mut writer, &ClientMessage::Authenticate(auth)).context("could not send authenticate")?;
                send_msg(&mut writer, &ClientMessage::Hello(req_port)).context("could not send hello")?;
                // wait for Hello response
