import socket, subprocess, time, threading
def free_port():
    s=socket.socket(); s.bind(("127.0.0.1",0)); p=s.getsockname()[1]; s.close(); return p
closed=free_port()
print(f"closed {closed}", flush=True)
for binpath in ["/tmp/myexe"]:
    print(f"\n=== {binpath} ===", flush=True)
    srv_proc=subprocess.Popen([binpath,"server","--bind-addr","127.0.0.1"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, bufsize=1)
    time.sleep(1)
    def log(p,prefix):
        try:
            for l in p.stdout:
                print(f"{prefix}: {l!r}", flush=True)
        except: pass
    threading.Thread(target=log, args=(srv_proc,"SRV"), daemon=True).start()
    local_proc=subprocess.Popen([binpath,"local",str(closed),"--to","127.0.0.1"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, bufsize=1)
    threading.Thread(target=log, args=(local_proc,"LOCAL"), daemon=True).start()
    time.sleep(2)
    def get_ports():
        ports=[]
        try:
            with open("/proc/net/tcp") as f:
                for line in f.readlines()[1:]:
                    parts=line.split()
                    if parts[3]=="0A":
                        ports.append(int(parts[1].split(":")[1],16))
        except: pass
        return ports
    ports=get_ports()
    cands=[p for p in ports if p not in (7835, closed)]
    print(f"cands {cands}", flush=True)
    if cands:
        rp=cands[0]
        s=socket.create_connection(("127.0.0.1",rp),timeout=5)
        s.sendall(b"hello")
        s.settimeout(3)
        try:
            d=s.recv(4096)
            print(f"recv {d!r}", flush=True)
        except Exception as e:
            print(f"err {e}", flush=True)
        s.close()
    time.sleep(2)
    local_proc.terminate(); srv_proc.terminate()
    try: local_proc.communicate(timeout=2)
    except: local_proc.kill()
    try: srv_proc.communicate(timeout=2)
    except: srv_proc.kill()
    time.sleep(0.5)
